import{_ as i,o as n,c as a,ag as l}from"./chunks/framework.PVHj0As1.js";const e="/pub-blog/assets/PixPin_2024-12-26_22-47-38.BkZJVMJG.gif",p="/pub-blog/assets/PixPin_2024-12-26_23-04-25.CGJb1UU1.gif",t="/pub-blog/assets/PixPin_2024-12-26_23-35-30.C1xBlLVI.gif",h="/pub-blog/assets/PixPin_2024-12-26_23-49-33.BK_nvvu0.gif",u=JSON.parse(`{"title":"HarmonyOS Next 弹窗系列教程（2）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（2）/HarmonyOS Next 弹窗系列教程（2）.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（2）/HarmonyOS Next 弹窗系列教程（2）.md","lastUpdated":1748912459000,"__rawMarkdown":"# HarmonyOS Next 弹窗系列教程（2）\\n\\n上一章节我们讲了自定义弹出框 (openCustomDialog)，那对于一些简单的业务场景，不一定需要都是自定义，也可以使用HarmonyOS Next 内置的一些弹窗效果。比如：\\n\\n| 名称                                                         | 描述                                                         |\\n| :----------------------------------------------------------- | :----------------------------------------------------------- |\\n| [不依赖UI组件的自定义弹出框 (openCustomDialog)](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-uicontext-custom-dialog-V5) | 当用户需要在自定义弹出框内动态更新弹出框属性时使用。         |\\n| [基础自定义弹出框-不推荐 (CustomDialog)](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-common-components-custom-dialog-V5) | 当用户需要自定义弹出框内的组件和内容时使用。                 |\\n| [警告弹窗 (AlertDialog)](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-fixes-style-dialog-V5#警告弹窗-alertdialog) | 固定样式，通常用来展示用户当前需要或必须关注的信息或操作。如用户操作一个敏感行为时响应一个二次确认的弹出框。 |\\n| [列表选择弹窗 (ActionSheet)](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-fixes-style-dialog-V5#列表选择弹出框-actionsheet) | 固定样式，当用户需要关注或确认的信息存在列表选择时使用。     |\\n| [选择器弹窗 (PickerDialog)](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-fixes-style-dialog-V5#选择器弹出框-pickerdialog) | 固定样式，当用户需要在弹出框内选择日期、时间和文本时使用。   |\\n| [对话框 (showDialog)](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-fixes-style-dialog-V5#对话框-showdialog) | 固定样式，当用户需要对在弹出框响应后异步返回结果进行处理时使用。 |\\n| [操作菜单 (showActionMenu)](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/arkts-fixes-style-dialog-V5#操作菜单-showactionmenu) | 固定样式，当用户需要对在操作菜单响应后异步返回结果进行处理时使用。 |\\n\\n## 警告弹窗 (AlertDialog)\\n\\n需要向用户提问或得到用户的许可时，可使用警告弹窗。\\n\\n- 警告弹窗用来提示重要信息，但会中断当前任务，尽量提供必要的信息和有用的操作。\\n- 避免仅使用警告弹窗提供信息，用户不喜欢被信息丰富但不可操作的警告打断。\\n\\n警告弹窗通过UIContext中的[showAlertDialog](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-arkui-uicontext-V5#showalertdialog)接口实现。\\n\\n### 效果：\\n\\n![PixPin_2024-12-26_22-47-38](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%882%EF%BC%89.assets/PixPin_2024-12-26_22-47-38.gif)\\n\\n\\n\\n\\n\\n### 示例代码\\n\\n根据上述的效果，我们发现需要配置的内容其实不少的：\\n\\n1. title  标题\\n2. message  对话框显示的消息内容\\n3. alignment  对话框在屏幕中的对齐方式\\n4. offset 对话框相对于默认位置的偏移量\\n5. gridCount 对话框内按钮布局的网格数量\\n6. transition  对话框的过渡效果设置\\n7. buttons 对话框的按钮配置数组\\n\\n\`\`\`tsx\\n@Entry\\n@Component\\nstruct showAlertDialogExample {\\n  build() {\\n    Column() {\\n      Button('showAlertDialog')// 设置按钮的外边距为30，具体单位可能根据框架默认设置（通常是像素相关单位）\\n        .margin(30)\\n        .onClick(() => {\\n          // 获取UI上下文环境，用于显示警告对话框\\n          this.getUIContext().showAlertDialog(\\n            {\\n              // 对话框的标题\\n              title: 'title',\\n              // 对话框显示的消息内容\\n              message: 'text',\\n              // 设置对话框是否能自动取消，这里设置为true表示可以自动取消\\n              autoCancel: true,\\n              // 对话框在屏幕中的对齐方式，这里设置为居中对齐\\n              alignment: DialogAlignment.Center,\\n              // 对话框相对于默认位置的偏移量，这里dx为0，dy为 -20，具体单位依框架而定\\n              offset: { dx: 0, dy: -20 },\\n              // 对话框内按钮布局的网格数量，此处设置为3（具体作用根据框架而定）\\n              gridCount: 3,\\n              // 对话框的过渡效果设置，通过组合不同的过渡效果来实现复杂的显示和隐藏动画\\n              transition: TransitionEffect.asymmetric(\\n                TransitionEffect.OPACITY.animation({ duration: 3000, curve: Curve.Sharp }).combine(\\n                  TransitionEffect.scale({ x: 1.5, y: 1.5 }).animation({ duration: 3000, curve: Curve.Sharp })\\n                ),\\n                TransitionEffect.OPACITY.animation({ duration: 100, curve: Curve.Smooth }).combine(\\n                  TransitionEffect.scale({ x: 0.5, y: 0.5 }).animation({ duration: 100, curve: Curve.Smooth })\\n                )\\n              ),\\n              // 对话框的按钮配置数组，定义了对话框中显示的按钮及其相应的行为\\n              buttons: [{\\n                // 按钮显示的值，这里是'cancel'\\n                value: 'cancel',\\n                // 点击该按钮时执行的回调函数，这里在控制台输出相应提示信息\\n                action: () => {\\n                  console.info('Callback when the first button is clicked')\\n                }\\n              },\\n                {\\n                  // 设置按钮是否可用，这里设置为true表示可用\\n                  enabled: true,\\n                  // 设置按钮是否默认获得焦点，这里设置为true表示默认获得焦点\\n                  defaultFocus: true,\\n                  // 设置按钮的样式，这里采用高亮样式\\n                  style: DialogButtonStyle.HIGHLIGHT,\\n                  // 按钮显示的值，这里是'ok'\\n                  value: 'ok',\\n                  // 点击该按钮时执行的回调函数，同样在控制台输出相应提示信息\\n                  action: () => {\\n                    console.info('Callback when the second button is clicked')\\n                  }\\n                }],\\n            }\\n          )\\n        })\\n    }\\n    .width('100%')\\n    .margin({ top: 5 })\\n  }\\n}\\n\`\`\`\\n\\n### 参考API\\n\\n实际开发中，根据官网[api](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V13/js-apis-arkui-uicontext-V13#showalertdialog)来调整代码 即可\\n\\n\\n\\n\\n\\n## 列表选择弹窗 (ActionSheet)\\n\\n列表选择器弹窗适用于呈现多个操作选项，尤其当界面中仅需展示操作列表而无其他内容时。\\n\\n列表选择器弹窗通过UIContext中的[showActionSheet](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-arkui-uicontext-V5#showactionsheet)接口实现。\\n\\n### 效果：\\n\\n![PixPin_2024-12-26_23-04-25](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%882%EF%BC%89.assets/PixPin_2024-12-26_23-04-25.gif)\\n\\n### 示例代码\\n\\n列表选择弹窗相比较于警告弹窗，重要的两个地方不一样了\\n\\n1. **showActionSheet**：用于展示操作表（Action Sheet）\\n2. **sheets**：操作表中各个选项（Sheet）的配置数组，每个选项包含标题以及点击时执行的动作（回调函数）\\n\\n\`\`\`jsx\\n@Entry\\n@Component\\nstruct showActionSheetExample {\\n  build() {\\n    Column() {\\n      Button('showActionSheet')\\n        .margin(30)\\n        .onClick(() => {\\n          // 通过获取UI上下文来调用showActionSheet方法，用于展示操作表（Action Sheet）\\n          this.getUIContext().showActionSheet({\\n            // 操作表的标题\\n            title: 'ActionSheet title',\\n            // 操作表显示的提示消息内容\\n            message: 'message',\\n            // 设置操作表是否能自动取消，这里设置为false，表示不会自动取消，需用户手动操作来关闭\\n            autoCancel: false,\\n            // 操作表的宽度，单位通常与UI框架默认的尺寸单位一致，这里设置为300（可能是像素等）\\n            width: 300,\\n            // 操作表的高度，单位同理，这里设置为300\\n            height: 300,\\n            // 操作表的圆角半径大小，用于设置其外观的圆润程度，这里是20（单位与整体尺寸单位一致）\\n            cornerRadius: 20,\\n            // 操作表边框的宽度，这里设置为1（单位与尺寸单位一致）\\n            borderWidth: 1,\\n            // 边框的样式，这里设置为实线（Solid），是BorderStyle枚举类型中的一种表示方式\\n            borderStyle: BorderStyle.Solid,\\n            // 边框的颜色，这里设置为蓝色（Color.Blue应该是框架预定义的颜色表示）\\n            borderColor: Color.Blue,\\n            // 操作表的背景颜色，设置为白色（Color.White同样是框架预定义颜色）\\n            backgroundColor: Color.White,\\n            // 操作表的过渡效果设置，通过组合不同的过渡动画效果来实现显示和隐藏时的动画表现\\n            transition: TransitionEffect.asymmetric(\\n              TransitionEffect.OPACITY.animation({ duration: 3000, curve: Curve.Sharp }).combine(\\n                TransitionEffect.scale({ x: 1.5, y: 1.5 }).animation({ duration: 3000, curve: Curve.Sharp })\\n              ),\\n              TransitionEffect.OPACITY.animation({ duration: 100, curve: Curve.Smooth }).combine(\\n                TransitionEffect.scale({ x: 0.5, y: 0.5 }).animation({ duration: 100, curve: Curve.Smooth })\\n              )\\n            ),\\n            // 操作表的确认按钮相关配置，包含按钮显示的值以及点击按钮时执行的回调函数\\n            confirm: {\\n              value: 'Confirm button',\\n              action: () => {\\n                console.info('Get Alert Dialog handled')\\n              }\\n            },\\n            // 操作表在屏幕中的对齐方式，这里设置为居中对齐（DialogAlignment.Center是框架预定义的对齐方式枚举值）\\n            alignment: DialogAlignment.Center,\\n            // 操作表中各个选项（Sheet）的配置数组，每个选项包含标题以及点击时执行的动作（回调函数）\\n            sheets: [\\n              {\\n                title: 'apples',\\n                action: () => {\\n                }\\n              },\\n              {\\n                title: 'bananas',\\n                action: () => {\\n                }\\n              },\\n              {\\n                title: 'pears',\\n                action: () => {\\n                  console.log('pears')\\n                }\\n              }\\n            ]\\n          })\\n        })\\n    }\\n    .width('100%')\\n    .margin({ top: 5 })\\n  }\\n}\\n\`\`\`\\n\\n### 参考API\\n\\n[链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-arkui-uicontext-V5#showactionsheet)\\n\\n\\n\\n## 对话框 (showDialog)\\n\\n对话框弹窗在日常使用中的频率非常高，比如 是否删除、是否弹出、确认支付等等场景。一般提供两个选择给用户，取消或者确定。\\n\\n### 效果：\\n\\n![PixPin_2024-12-26_23-35-30](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%882%EF%BC%89.assets/PixPin_2024-12-26_23-35-30.gif)\\n\\n### 示例代码\\n\\n\\n\\n\`\`\`jsx\\n@Entry\\n@Component\\nstruct Index {\\n  build() {\\n    Column() {\\n      Button(\\"showDialog\\")\\n        .margin(20)\\n        .onClick(() => {\\n          let uiContext = this.getUIContext();\\n          let promptAction = uiContext.getPromptAction();\\n          promptAction.showDialog({\\n            // 设置对话框的标题为'showDialog Title Info'，\\n            title: 'showDialog Title Info',\\n            // 设置对话框中要显示的消息内容为'Message Info'，\\n            message: 'Message Info',\\n            // 配置对话框中要显示的按钮数组，\\n            buttons: [\\n              {\\n                text: 'button1',\\n                color: '#000000'\\n              },\\n              {\\n                text: 'button2',\\n                color: '#000000'\\n              }\\n            ]\\n          }, (err, data) => {\\n            if (err) {\\n              console.error('showDialog err: ' + err);\\n              return;\\n            }\\n            console.info('showDialog success callback, click button: ' + data.index);\\n          });\\n        })\\n    }\\n    .width('100%')\\n  }\\n}\\n\`\`\`\\n\\n\\n\\n### 参考API\\n\\n[链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-arkui-uicontext-V5#showalertdialog)\\n\\n## 操作菜单 (showActionMenu)\\n\\n操作菜单的功能比较明显，就是弹出一个弹窗，内容是类似一些菜单提供用户选择。\\n\\n\\n\\n### 效果\\n\\n![PixPin_2024-12-26_23-49-33](HarmonyOS%20Next%20%E5%BC%B9%E7%AA%97%E7%B3%BB%E5%88%97%E6%95%99%E7%A8%8B%EF%BC%882%EF%BC%89.assets/PixPin_2024-12-26_23-49-33.gif)\\n\\n### 示例代码\\n\\n\`\`\`jsx\\n@Entry\\n@Component\\nstruct Index {\\n  build() {\\n    Column() {\\n      Button(\\"showDialog\\")\\n        .margin(20)\\n        .onClick(() => {\\n\\n          let uiContext = this.getUIContext();\\n          let promptAction = uiContext.getPromptAction();\\n          promptAction.showActionMenu({\\n            title: 'showActionMenu Title Info',\\n            buttons: [\\n              {\\n                text: 'item1',\\n                color: '#666666'\\n              },\\n              {\\n                text: 'item2',\\n                color: '#000000'\\n              },\\n            ]\\n          })\\n            .then(data => {\\n              console.info('showActionMenu success, click button: ' + data.index);\\n            })\\n\\n        })\\n    }\\n    .width('100%')\\n  }\\n}\\n\`\`\`\\n\\n\\n\\n### 参考API\\n\\n[链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-arkui-uicontext-V5#showactionmenu11)\\n\\n\\n\\n\\n\\n## 总结\\n\\n在实际开发中，可以优先针对适合的场景来选择合适的弹窗"}`),k={name:"鸿蒙开发技巧/HarmonyOS Next 弹窗系列教程/HarmonyOS Next 弹窗系列教程（2）/HarmonyOS Next 弹窗系列教程（2）.md"};function r(E,s,o,c,d,g){return n(),a("div",null,[...s[0]||(s[0]=[l("",44)])])}const b=i(k,[["render",r]]);export{u as __pageData,b as default};
